-- 3 Nov 2026 (run by Claude through the SQL tool): the Energy page now reads the plugs every 5 seconds
-- while it's open, so energy_ingest keeps at most one stored reading a minute per plug. The use between
-- readings is still counted every time (from the running total on the plug's row), so energy_days is unchanged.
CREATE OR REPLACE FUNCTION public.energy_ingest(p_device uuid, p_at timestamp with time zone, p_watts real, p_total double precision, p_on boolean)
 RETURNS double precision
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ declare d public.energy_devices%rowtype; used double precision := 0; span double precision; cur date; last_day date; part double precision; begin select * into d from public.energy_devices where id = p_device for update; if not found then return 0; end if; if d.read_at is not null and p_at <= d.read_at then return 0; end if; if not exists (select 1 from public.energy_readings r where r.device_id = p_device and r.at > p_at - interval '55 seconds') then insert into public.energy_readings (user_id, device_id, at, watts, total_wh, is_on) values (d.user_id, p_device, p_at, p_watts, p_total, p_on); end if; if d.read_at is not null and d.total_wh is not null then used := p_total - d.total_wh; if used < -0.5 then used := p_total; elsif used < 0 then used := 0; end if; if used > 4000 * extract(epoch from (p_at - d.read_at)) / 3600 then used := 0; end if; end if; if used > 0 then span := extract(epoch from (p_at - d.read_at)); cur := (d.read_at at time zone 'Europe/London')::date; last_day := (p_at at time zone 'Europe/London')::date; loop part := case when last_day - cur > 400 then used else used * extract(epoch from ( least(p_at, ((cur + 1)::timestamp at time zone 'Europe/London')) - greatest(d.read_at, (cur::timestamp at time zone 'Europe/London')))) / span end; if last_day - cur > 400 then cur := last_day; end if; if part > 0 then insert into public.energy_days (device_id, day, user_id, wh, updated_at) values (p_device, cur, d.user_id, part, now()) on conflict (device_id, day) do update set wh = public.energy_days.wh + excluded.wh, updated_at = now(); end if; exit when cur >= last_day; cur := cur + 1; end loop; end if; update public.energy_devices set total_wh = p_total, read_at = p_at, watts = p_watts, is_on = p_on, online = true where id = p_device; return used; end $function$;
